91	export type LinkErrorPanelProps = {
92	  cluster: ClusterAttributes;
93	  errorMessage?: string;
94	  children?: React.ReactNode;
95	};
96	
97	/**
98	 *
99	 *
100	 * @public
101	 */
102	export const LinkErrorPanel = ({
103	  cluster,
104	  errorMessage,
105	}: LinkErrorPanelProps) => (
106	  <WarningPanel
107	    title="There was a problem formatting the link to the Kubernetes dashboard"
108	    message={`Could not format the link to the dashboard of your cluster named '${
109	      cluster.name
110	    }'. Its dashboardApp property has been set to '${
111	      cluster.dashboardApp || 'standard'
112	    }.'`}
113	  >
114	    {errorMessage && (
115	      <Typography variant="body2">Errors: {errorMessage}</Typography>
116	    )}
117	  </WarningPanel>
118	);
