34	
35	type IngressAccordionProps = {
36	  ingress: V1Ingress;
37	};
38	
39	type IngressSummaryProps = {
40	  ingress: V1Ingress;
41	};
42	
43	const IngressSummary = ({ ingress }: IngressSummaryProps) => {
44	  return (
45	    <Grid
46	      container
47	      direction="row"
48	      justifyContent="flex-start"
49	      alignItems="center"
50	    >
51	      <Grid xs={12} item>
52	        <IngressDrawer ingress={ingress} />
53	      </Grid>
54	    </Grid>
55	  );
56	};
57	
58	type IngressCardProps = {
59	  ingress: V1Ingress;
60	};
61	
62	const IngressCard = ({ ingress }: IngressCardProps) => {
63	  return (
64	    <StructuredMetadataTable
65	      metadata={{
66	        ...ingress.spec,
67	      }}
68	    />
69	  );
70	};
71	
72	const IngressAccordion = ({ ingress }: IngressAccordionProps) => {
73	  return (
74	    <Accordion TransitionProps={{ unmountOnExit: true }}>
75	      <AccordionSummary expandIcon={<ExpandMoreIcon />}>
